#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_refComp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_refComp(uv);return float4(0.0); }
uniform float amzp_completion;
uniform float amzp_style;
uniform float amzp_phase;
uniform float amzp_amount;
uniform float amzp_easePow;
uniform float2 amzp_center;
uniform float amzp_mirrorOn;
uniform float amzp_blurAmt;
uniform float amzp_rgbSplit;
uniform float amzp_flash;
uniform float amzp_source;
uniform float amzp_samples;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float4 layerClamp(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_aSpeed * 0.5) : p; }
    float2 mirrorUV(float2 uv) { return 1.0 - abs(1.0 - mod(uv, 2.0)); }
    float4 srcAt(float2 uv) {
        if ((amzp_mirrorOn>0.5)) uv = mirrorUV(uv);
        if (int(amzp_source) == 1) return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(1, uv) : float4(0.0);
        return layerAt(uv);
    }
    float2 xform(float2 P, float c, float2 W) {
        float k = max(amzp_easePow, 1.0);
        float am = max(amzp_amount, 0.0);
        bool inP; float p;
        if (int(amzp_phase) == 0) { inP = false; p = c; }
        else if (int(amzp_phase) == 1) { inP = true; p = c; }
        else { inP = c >= 0.5; p = inP ? c * 2.0 - 1.0 : c * 2.0; }
        p = clamp(p, 0.0, 1.0);
        float e = inP ? pow(1.0 - p, k) : pow(p, k);
        float sg = inP ? -1.0 : 1.0;
        float Z = 1.0 + am * 3.0;
        float th = am * 6.28318531;
        float2 dir = advRot(float2(1.0, 0.0), radians(amzp_advAngle));
        float2 nrm = float2(-dir.y, dir.x);
        float dLen = abs(dir.x) * W.x + abs(dir.y) * W.y;
        float2 Q = P / max(amzp_advScale, 0.01);
        if (int(amzp_style) == 0) Q /= pow(Z, sg * e);
        else if (int(amzp_style) == 1) Q /= pow(Z, -sg * e);
        else if (int(amzp_style) == 2) Q = advRot(Q, sg * th * e);
        else if (int(amzp_style) == 3) Q = advRot(Q, -sg * th * e);
        else if (int(amzp_style) == 4) Q += dir * dLen * am * e * sg;
        else if (int(amzp_style) == 5) Q -= dir * dLen * am * e * sg;
        else if (int(amzp_style) == 6) Q -= nrm * (abs(nrm.x) * W.x + abs(nrm.y) * W.y) * am * e * sg;
        else if (int(amzp_style) == 7) Q += nrm * (abs(nrm.x) * W.x + abs(nrm.y) * W.y) * am * e * sg;
        else if (int(amzp_style) == 8 || int(amzp_style) == 9) {
            float2 ax = int(amzp_style) == 8 ? dir : nrm;
            float a1 = dot(Q, ax);
            float2 rest = Q - ax * a1;
            Q = rest + ax * a1 / pow(Z, e);
        } else {
            Q = advRot(Q / pow(Z, sg * e * 0.6), sg * th * 0.5 * e);
        }
        return Q;
    }
    void nmFxMain() {
        bool useComp = int(amzp_source) == 1;
        float2 W = useComp ? screen.zw : layer;
        float2 uv0 = useComp ? amzScreenNorm() : amzLayerNorm();
        float2 ctrL = float2(0.5) + float2(amzp_center.x, -amzp_center.y) * pxs() / layer;
        float2 ctr = useComp ? l2s(ctrL) : ctrL;
        float2 P = (uv0 - ctr) * W;
        float C = clamp(prog(amzp_completion), 0.0, 1.0);
        if ((amzp_autop>0.5)) C = fract(prog(amzp_completion));
        float N = floor(clamp(amzp_samples, 1.0, 64.0) + 0.5);
        float win = amzp_blurAmt * 0.07;
        float spl = amzp_rgbSplit * 0.035;
        float4 acc = float4(0.0);
        float ws = 0.0;
        for (int i = 0; i < 64; i++) {
            float fi = float(i);
            if (fi >= N) break;
            float o = N > 1.0 ? fi / (N - 1.0) - 0.5 : 0.0;
            float cj = clamp(C + o * win, 0.0, 1.0);
            float w = 1.0 - abs(o) * 0.8;
            float4 s = srcAt(ctr + xform(P, cj, W) / W);
            if (spl > 0.0) {
                float4 sr = srcAt(ctr + xform(P, clamp(cj + spl, 0.0, 1.0), W) / W);
                float4 sb = srcAt(ctr + xform(P, clamp(cj - spl, 0.0, 1.0), W) / W);
                s = float4(sr.r, s.g, sb.b, max(s.a, max(sr.a, sb.a)));
            }
            acc += s * w;
            ws += w;
        }
        float4 R = acc / max(ws, 1e-5);
        if (amzp_flash > 0.0) {
            float pk = int(amzp_phase) == 0 ? 1.0 : (int(amzp_phase) == 1 ? 0.0 : 0.5);
            float d = (C - pk) / 0.09;
            R.rgb = min(R.rgb + float3(amzp_flash * exp(-d * d)) * R.a, float3(R.a));
        }
        amzOutput = R;
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5) && int(amzp_source) == 0) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
